List<String> getWilayaNames() =>
    kAlgeriaWilayas.map((w) => w.nameAr).toList();

List<String> getCommunesForWilaya(String wilayaName) {
  final wilaya = kAlgeriaWilayas.firstWhere(
    (w) => w.nameAr == wilayaName,
    orElse: () => const Wilaya(code: '', nameAr: '', nameFr: '', communes: []),
  );
  return wilaya.communes;
}

int get wilayaCount => kAlgeriaWilayas.length;
